// Generated by scripts/embed-presets.ts from presets/omp/*.md. Do not edit.
export const OMP_PRESET: Readonly<Record<string, string>> = {
  "go-add-cleanup": "---\ndescription: \"Prefer runtime.AddCleanup over runtime.SetFinalizer for new code (Go 1.24)\"\ncondition: 'runtime\\.SetFinalizer'\nscope: \"tool:edit(*.go), tool:write(*.go)\"\ninterruptMode: never\n---\n\nGo 1.24 added `runtime.AddCleanup`; new code SHOULD prefer it over `runtime.SetFinalizer`.\n\n## Why AddCleanup wins\n\n- One object — multiple cleanups; `SetFinalizer`: one.\n- Cleanups MAY attach to interior pointers.\n- Reference cycles: cleanups run; finalizers leak.\n- Cleanup neither resurrects object nor delays freeing it or its referents an extra GC cycle.\n\n## Migration\n\n```go\n// Before\nruntime.SetFinalizer(obj, func(o *T) { o.release() })\n\n// After — the cleanup func receives a value you supply, NOT the object,\n// so it cannot accidentally keep the object alive.\nruntime.AddCleanup(obj, func(h handle) { h.release() }, obj.handle)\n```\n\nCleanup argument MUST NOT reference `obj` itself: it remains reachable forever. Capture only needed data: file descriptor, handle, or pointer independent of `obj`.\n\n## Keep SetFinalizer only when\n\n- Module targets Go <1.24.\n- Finalizer-specific behavior required, e.g. object resurrection, which `AddCleanup` does not provide.\n",
  "go-bench-loop": "---\ndescription: \"Use for b.Loop() in benchmarks instead of the for i := 0; i < b.N; i++ loop (Go 1.24)\"\ninterruptMode: never\nscope: \"tool:edit(*_test.go), tool:write(*_test.go)\"\nastCondition:\n  - \"func $F($B *testing.B) { $$$PRE for $I := 0; $I < $B.N; $I++ { $$$BODY } $$$POST }\"\n---\n\nGo 1.24 added `testing.B.Loop`. Write `for b.Loop() { ... }` instead of looping over `b.N`.\n\n## Why\n\n- Setup and teardown outside the loop run exactly once per `-count`, not once per `b.N` re-estimation, so expensive fixtures are no longer timed or repeated.\n- The compiler keeps the loop's parameters and results alive, so it can't optimize away the body you are trying to measure — a classic `b.N` benchmarking footgun.\n\n## Avoid\n\n```go\nfunc BenchmarkEncode(b *testing.B) {\n\tfor i := 0; i < b.N; i++ {\n\t\tEncode(input)\n\t}\n}\n```\n\n## Use\n\n```go\nfunc BenchmarkEncode(b *testing.B) {\n\tfor b.Loop() {\n\t\tEncode(input)\n\t}\n}\n```\n\nRequires Go 1.24+. If the module targets an older Go, keep the `b.N` loop.\n",
  "go-exp-promoted": "---\ndescription: \"Use the standard library slices and maps packages instead of golang.org/x/exp/{slices,maps}\"\ncondition:\n  - '\"golang.org/x/exp/slices\"'\n  - '\"golang.org/x/exp/maps\"'\nscope: \"tool:edit(*.go), tool:write(*.go)\"\ninterruptMode: never\n---\n\nGo 1.21: `golang.org/x/exp/slices` and `golang.org/x/exp/maps` → stdlib `slices` and `maps`. New code: stdlib imports, not experimental.\n\n## Migration\n\n```go\n// Before\nimport (\n\t\"golang.org/x/exp/slices\"\n\t\"golang.org/x/exp/maps\"\n)\n\n// After\nimport (\n\t\"slices\"\n\t\"maps\"\n)\n```\n\nMost call sites unchanged: `slices.Sort`, `slices.Contains`, `slices.Index`, `slices.Equal`, `maps.Clone`, etc.\n\n## Signature differences\n\nPromoted APIs tweaked; blind path swap can break the build:\n\n- `x/exp/maps.Keys(m)` and `x/exp/maps.Values(m)`: slice; stdlib `maps.Keys(m)` and `maps.Values(m)`: iterator (`iter.Seq`). Recover a slice: `slices.Collect(maps.Keys(m))`; or range over the iterator.\n- `slices.SortFunc`: comparison returns `int` (cmp-style), matching stdlib signature.\n\n## Keep x/exp when\n\n- Module `go` directive below 1.21 → stdlib `slices`/`maps` do not exist.\n- Need an unpromoted `x/exp` helper, e.g. parts of `x/exp/constraints` remain outside stdlib.\n",
  "go-ioutil": "---\ndescription: \"Use io and os instead of the deprecated io/ioutil package\"\ncondition: '\"io/ioutil\"'\nscope: \"tool:edit(*.go), tool:write(*.go)\"\ninterruptMode: never\n---\n\n`io/ioutil`: deprecated since Go 1.16. All functions moved to `io` or `os`; same behavior except `ReadDir`. New code: NEVER import `io/ioutil`.\n\n## Mapping\n\n|io/ioutil|Replacement|\n|---|---|\n|`ioutil.ReadAll`|`io.ReadAll`|\n|`ioutil.ReadFile`|`os.ReadFile`|\n|`ioutil.WriteFile`|`os.WriteFile`|\n|`ioutil.ReadDir`|`os.ReadDir`|\n|`ioutil.TempFile`|`os.CreateTemp`|\n|`ioutil.TempDir`|`os.MkdirTemp`|\n|`ioutil.NopCloser`|`io.NopCloser`|\n|`ioutil.Discard`|`io.Discard`|\n\n## Migration\n\n```go\n// Before\nimport \"io/ioutil\"\ndata, err := ioutil.ReadFile(path)\n_ = ioutil.WriteFile(out, data, 0o644)\n\n// After\nimport \"os\"\ndata, err := os.ReadFile(path)\n_ = os.WriteFile(out, data, 0o644)\n```\n\n`os.ReadDir`: returns `[]os.DirEntry`, not `[]os.FileInfo`; for old `FileInfo`, call `entry.Info()`. Other mappings: drop-in renames.\n",
  "go-join-hostport": "---\ndescription: \"Build network addresses with net.JoinHostPort, not fmt.Sprintf(\\\"%s:%d\\\", host, port) — the Sprintf form breaks on IPv6\"\ncondition: 'fmt\\.Sprintf\\(\"%s:%d\"'\nscope: \"tool:edit(*.go), tool:write(*.go)\"\ninterruptMode: never\n---\n\nUse `net.JoinHostPort(host, port)` to assemble a `host:port` address. `fmt.Sprintf(\"%s:%d\", host, port)` produces invalid addresses for IPv6 hosts, which must be bracketed (`[::1]:80`). Go 1.25's `go vet` `hostport` analyzer flags exactly this pattern.\n\n## Why\n\n- An IPv6 literal like `::1` has its own colons, so `fmt.Sprintf(\"%s:%d\", \"::1\", 80)` yields `::1:80` — unparseable by `net.Dial`.\n- `net.JoinHostPort` adds the brackets when the host contains a colon and leaves IPv4/hostnames untouched.\n\n## Avoid\n\n```go\naddr := fmt.Sprintf(\"%s:%d\", host, port)\nconn, err := net.Dial(\"tcp\", addr)\n```\n\n## Use\n\n```go\n// port is a string here; convert an int with strconv.Itoa.\naddr := net.JoinHostPort(host, strconv.Itoa(port))\nconn, err := net.Dial(\"tcp\", addr)\n```\n\n`net.JoinHostPort` takes the port as a string. For an `int` port, wrap it in `strconv.Itoa`. The function is available in every supported Go version.\n",
  "go-new-expr": "---\ndescription: \"Use new(expr) for pointer-to-value helpers instead of `func ptr[T any](v T) *T { return &v }` (Go 1.26)\"\ninterruptMode: never\nscope: \"tool:edit(*.go), tool:write(*.go)\"\nastCondition:\n  - \"func $F($V $T) *$T { return &$V }\"\n  - \"func $F[$$$TP]($V $T) *$T { return &$V }\"\n---\n\nGo 1.26: `new(expr)` allocates, stores `expr`, returns `*T`; replaces pointer-value helpers and `x := v; p := &x`.\n\n## Why\n\n- Replaces per-type helpers (`boolPtr`, `strPtr`, `int64Ptr`, …) and `func Ptr[T any](v T) *T`.\n- Value constructed directly in allocation: no extra function-call frame or separate heap escape.\n- Call-site intent visible: `new(false)`, not a helper name.\n\n## Avoid\n\n```go\n// A helper that just takes a value and returns its address.\nfunc boolPtr(v bool) *bool   { return &v }\nfunc strPtr(v string) *string { return &v }\nfunc Ptr[T any](v T) *T       { return &v }\n\ncfg := Config{Enabled: boolPtr(true), Name: strPtr(\"svc\")}\n```\n\n## Use\n\n```go\ncfg := Config{Enabled: new(true), Name: new(\"svc\")}\n\n// Was: x := int64(300); p := &x\np := new(int64(300))\n```\n\n`new(true)` / `new(false)`: `*bool`. `new(expr)`: any expression, including function results (`new(time.Now())`).\n\n## Notes\n\n- Requires Go 1.26+. If the module's `go` directive is older, keep the helper or temp-variable form until the toolchain is bumped.\n- Scope: helpers only taking a value and returning its address; functions doing work before taking an address excluded.\n- `new(T)` (bare type) unchanged; still zero-initializes.\n",
  "go-rand-v2": "---\ndescription: Prefer math/rand/v2 over the legacy math/rand package\ncondition: '\"math/rand\"'\nscope: \"tool:edit(*.go), tool:write(*.go)\"\ninterruptMode: never\n---\n\nUse `math/rand/v2` instead of the legacy `math/rand` package (stable since Go 1.22).\n\n## Why\n\n- No global `Seed`: `math/rand`'s top-level functions read a process-global generator (auto-seeded since Go 1.20), so a fixed seed is global mutable state that's easy to misuse; `v2` drops the global `Seed` entirely.\n- Cleaner, better-bounded API: `rand.IntN(n)` / generic `rand.N(n)` replace `rand.Intn(n)`, and `Shuffle`, `Perm`, `Float64` carry over with clearer names.\n- Modern generators: `v2` exposes `PCG` and `ChaCha8` sources instead of the old default LCG.\n\n## Migration\n\n```go\n// Before\nimport \"math/rand\"\nn := rand.Intn(100)\nf := rand.Float64()\n\n// After\nimport \"math/rand/v2\"\nn := rand.IntN(100)\nf := rand.Float64()\n```\n\n| math/rand | math/rand/v2 |\n| --- | --- |\n| `rand.Intn(n)` | `rand.IntN(n)` |\n| `rand.Int63n(n)` | `rand.Int64N(n)` |\n| `rand.Intn`/`Int31n` on a `*Rand` | `(*Rand).IntN` / `Int32N` |\n| `rand.Seed(x)` | drop it — `v2` has no global seed |\n| explicit `rand.New(rand.NewSource(seed))` | `rand.New(rand.NewPCG(s1, s2))` or `rand.NewChaCha8(seed)` |\n\n## Keep math/rand only when\n\n- You need a reproducible stream from a fixed seed via the classic `NewSource`/`Seed` API that a caller already depends on.\n- Reach for `crypto/rand` instead when the values are security-sensitive — neither `math/rand` variant is cryptographically secure.\n",
  "go-range-int": "---\ndescription: \"Use for i := range n instead of the C-style for i := 0; i < n; i++ loop (Go 1.22)\"\ninterruptMode: never\nscope: \"tool:edit(*.go), tool:write(*.go)\"\nastCondition:\n  - \"for $I := 0; $I < $N; $I++ { $$$BODY }\"\n---\n\nGo 1.22: `for` ranges integers. For `i := 0; i < n; i++`, prefer `for i := range n`; if index unused, `for range n`.\n\n## Avoid\n\n```go\nfor i := 0; i < n; i++ {\n\tuse(i)\n}\n\nfor i := 0; i < len(s); i++ {\n\tuse(s[i])\n}\n```\n\n## Use\n\n```go\nfor i := range n {\n\tuse(i)\n}\n\n// Ranging the slice directly is usually clearer than indexing.\nfor i := range s {\n\tuse(s[i])\n}\n\n// Index unused → drop it entirely.\nfor range n {\n\ttick()\n}\n```\n\n## Exceptions\n\n- Keep explicit: non-zero start; step other than `++`; descending (`for i := n - 1; i >= 0; i--`).\n- Keep explicit if body reassigns loop variable or depends on `i` surviving past loop.\n- Requires Go 1.22+. If module `go` directive older, keep classic loop.\n",
  "rs-box-leak": "---\ndescription: Never use Box::leak - it intentionally leaks memory\ncondition: \"Box::leak\"\nscope: \"tool:edit(*.rs), tool:write(*.rs)\"\ninterruptMode: never\n---\n\nNever use `Box::leak` to satisfy a lifetime. It intentionally leaks the allocation for the rest of the process.\n\n## Why\n\n- The allocation is never freed.\n- It hides ownership bugs.\n- It turns lifetime errors into process lifetime growth.\n- It makes tests pass while production memory grows.\n\n## Use instead\n\n|Need|Use|\n|---|---|\n|Shared async/thread data|`Arc<T>` or owned values|\n|Global lazy state|`LazyLock<T>` or `OnceLock<T>`|\n|Text escaping a scope|`String` / `Arc<str>`|\n|`'static` callback|`move` closure with owned captures|\n|FFI pointer|Explicit owner that frees on drop|\n\n## Examples\n\n```rust\n// Bad — leaking to manufacture 'static.\nfn label(id: u64) -> &'static str {\n    Box::leak(Box::new(format!(\"item_{id}\")))\n}\n\n// Good — return owned data.\nfn label(id: u64) -> String {\n    format!(\"item_{id}\")\n}\n\n// Bad — leaking before spawn.\nlet state = Box::leak(Box::new(state));\ntokio::spawn(async move { use_state(state) });\n\n// Good — share owned state.\nlet state = Arc::new(state);\ntokio::spawn(async move { use_state(&state) });\n```\n\nIf `Box::leak` looks necessary, fix ownership instead.\n",
  "rs-future-prelude": "---\ndescription: Use Future not std::future::Future - it's in the prelude\ncondition: \"std::future::Future\"\nscope: \"tool:edit(*.rs), tool:write(*.rs)\"\ninterruptMode: never\n---\n\nType positions: use `Future`, not `std::future::Future`.\n\nRust 2024 standard prelude: `Future`.\nPre-2024: add once at top: `use std::future::Future;`.\nRepeated fully qualified paths: harder-to-read signatures, no added safety.\n\n## Examples\n\n```rust\n// Bad — fully qualified in every signature.\nfn fetch() -> impl std::future::Future<Output = Result<Data>> { ... }\nfn poll(fut: Pin<&mut dyn std::future::Future<Output = i32>>) { ... }\n\n// Good — use the prelude or one import.\nfn fetch() -> impl Future<Output = Result<Data>> { ... }\nfn poll(fut: Pin<&mut dyn Future<Output = i32>>) { ... }\n```\n",
  "rs-lazylock": "---\ndescription: Prefer std::sync::LazyLock over OnceLock and once_cell\ncondition:\n  - \"once_cell::\"\n  - \"OnceLock::new\"\nscope: \"tool:edit(*.rs), tool:write(*.rs)\"\ninterruptMode: never\n---\n\nPrefer `std::sync::LazyLock` over `OnceLock` and the `once_cell` crate when the initializer is known at declaration time.\n\n`LazyLock` stores the cell and initializer together. There is no separate `init()` function, no repeated `get_or_init`, and no missing initialization path.\n\n## once_cell → std\n\n```rust\n// Before\nuse once_cell::sync::Lazy;\nstatic CONFIG: Lazy<String> = Lazy::new(|| \"value\".to_string());\n\n// After\nuse std::sync::LazyLock;\nstatic CONFIG: LazyLock<String> = LazyLock::new(|| \"value\".to_string());\n```\n\n## OnceLock → LazyLock\n\n```rust\n// Before — fixed initializer hidden in accessor.\nuse std::sync::OnceLock;\nstatic SETTINGS: OnceLock<Settings> = OnceLock::new();\nfn settings() -> &'static Settings {\n    SETTINGS.get_or_init(Settings::load)\n}\n\n// After — initializer lives with the static.\nuse std::sync::LazyLock;\nstatic SETTINGS: LazyLock<Settings> = LazyLock::new(Settings::load);\n```\n\n## Keep OnceLock when runtime input is required\n\n```rust\nuse std::sync::OnceLock;\nstatic DATABASE: OnceLock<Database> = OnceLock::new();\n\nfn init_database(url: &str) {\n    let _ = DATABASE.set(Database::connect(url));\n}\n```\n\nDo not add `once_cell` for new code. Use the standard library equivalent.\n",
  "rs-match-ergonomics": "---\ndescription: Use match ergonomics instead of ref/ref mut patterns\ncondition:\n  - \"\\\\(ref mut \"\n  - \"\\\\(ref [a-z_]\"\nscope: \"tool:edit(*.rs), tool:write(*.rs)\"\ninterruptMode: never\n---\n\nUse match ergonomics instead of explicit `ref` / `ref mut` patterns. Borrow the scrutinee and let bindings receive references.\n\n## Shared references\n\n```rust\n// Before\nmatch value {\n    Some(ref item) => println!(\"{item}\"),\n    None => {}\n}\n\n// After\nmatch &value {\n    Some(item) => println!(\"{item}\"),\n    None => {}\n}\n\nif let Some(item) = &value {\n    println!(\"{item}\");\n}\n```\n\n## Mutable references\n\n```rust\n// Before\nmatch value {\n    Some(ref mut item) => *item += 1,\n    None => {}\n}\n\n// After\nmatch &mut value {\n    Some(item) => *item += 1,\n    None => {}\n}\n\nif let Some(item) = &mut value {\n    *item += 1;\n}\n```\n\n## Result\n\n```rust\n// Before\nmatch result {\n    Ok(ref data) => println!(\"{data}\"),\n    Err(ref err) => eprintln!(\"{err}\"),\n}\n\n// After\nmatch &result {\n    Ok(data) => println!(\"{data}\"),\n    Err(err) => eprintln!(\"{err}\"),\n}\n```\n\nModern Rust rarely needs `ref` in patterns. Borrow the value being matched.\n",
  "rs-parking-lot": "---\ndescription: Use parking_lot instead of std::sync for Mutex/RwLock\ncondition:\n  - \"\\\\.lock\\\\(\\\\)\\\\.unwrap\\\\(\\\\)\"\n  - \"\\\\.read\\\\(\\\\)\\\\.unwrap\\\\(\\\\)\"\n  - \"\\\\.write\\\\(\\\\)\\\\.unwrap\\\\(\\\\)\"\nscope: \"tool:edit(*.rs), tool:write(*.rs)\"\ninterruptMode: never\n---\n\nUse `parking_lot::{Mutex, RwLock}` instead of `std::sync::{Mutex, RwLock}` when code immediately unwraps lock results.\n\n## Why\n\n- `lock()`, `read()`, and `write()` return guards directly.\n- No poisoning error path to unwrap.\n- Guards are smaller and faster in common contention cases.\n- The call site shows locking, not error handling boilerplate.\n\n## Migration\n\n```rust\n// Before\nuse std::sync::Mutex;\nlet data = Mutex::new(Vec::new());\nlet guard = data.lock().unwrap();\n\n// After\nuse parking_lot::Mutex;\nlet data = Mutex::new(Vec::new());\nlet guard = data.lock();\n```\n\n## Equivalents\n\n|std::sync|parking_lot|\n|---|---|\n|`Mutex<T>`|`Mutex<T>`|\n|`RwLock<T>`|`RwLock<T>`|\n|`Condvar`|`Condvar`|\n|`Once`|`Once`|\n\n## Keep async locks async\n\nUse `tokio::sync::Mutex` / `tokio::sync::RwLock` when a guard is held across `.await` or the lock belongs to async coordination.\n",
  "rs-result-type": "---\ndescription: Result type aliases must include a defaulted error type parameter\ncondition: \"type\\\\s+Result<[A-Za-z_]\\\\w*>\\\\s*=\"\nscope: \"tool:edit(*.rs), tool:write(*.rs)\"\ninterruptMode: never\n---\n\n`Result` aliases must expose the error type as a defaulted parameter.\n\n```rust\npub type Result<T, E = anyhow::Error> = std::result::Result<T, E>;\n```\n\nNever write:\n\n```rust\ntype Result<T> = std::result::Result<T, anyhow::Error>;\n```\n\nThe default keeps common call sites short while preserving escape hatches for precise errors.\n",
  "ts-bare-catch": "---\ndescription: Use bare `catch {` when the error binding is unused\ncondition: \"catch \\\\(_\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nUse bare `catch {}` when the caught value is unused. An underscore-prefixed binding adds noise and still allocates a local name.\n\n## Replace\n\n```typescript\n// Bad\ntry {\n\tawait loadConfig();\n} catch (_err) {\n\treturn null;\n}\n\n// Good\ntry {\n\tawait loadConfig();\n} catch {\n\treturn null;\n}\n```\n\n## Keep a real name when used\n\n```typescript\ntry {\n\tawait saveConfig();\n} catch (err) {\n\tlogger.error(\"save failed\", { err });\n\tthrow err;\n}\n```\n\nUnused error? Bare `catch`. Used error? Name it for what it carries.\n",
  "ts-import-type": "---\ndescription: \"Use `import type`, not `import('pkg').Type` in type positions\"\ncondition: \"import\\\\(\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nUse top-level `import type` declarations for type-only dependencies. NEVER write `import(\"pkg\").Type` inside source annotations.\n\n## Why\n\n- Top-level imports expose dependencies immediately.\n- Import sorting and deduplication can manage them.\n- Signatures stay readable and reviewable.\n- Re-exports do not inherit noisy inline paths.\n\n## Avoid\n\n```typescript\n// Bad — inline imports hide dependencies in signatures.\nfunction run(client: import(\"some-sdk\").Client, input: import(\"arktype\").infer<Schema>): Promise<Output>;\n\n// Bad — annotations become path dumps.\nconst options: import(\"some-sdk/config\").ClientOptions = { ... };\n```\n\n## Use\n\n```typescript\nimport type { Client } from \"some-sdk\";\nimport type { ClientOptions } from \"some-sdk/config\";\nimport type { infer as Infer } from \"arktype\";\n\nfunction run(client: Client, input: Infer<Schema>): Promise<Output>;\nconst options: ClientOptions = { ... };\n```\n\n## Exceptions\n\n- Ambient `.d.ts` globals that must not become modules.\n- Generated files whose generator owns import management.\n\nIn normal `.ts` / `.tsx` source, use `import type`.\n",
  "ts-no-any": "---\ndescription: \"Never use `any` in TypeScript annotations or assertions — use `unknown`, generics, a schema parse at trust boundaries, or the actual type\"\ncondition: \": any|as any\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nNever use `: any` or `as any`. They disable type checking exactly where the boundary needs precision.\n\n## Use instead\n\n- `unknown` for unvalidated input.\n- A schema parse (Zod, Valibot, …; e.g. Zod v4 when it is already in the project) for untrusted or external input — validate once, then consume a typed value.\n- A domain type when the shape is known.\n- A generic when the caller supplies the shape.\n- A type guard when runtime checks establish shape.\n- `satisfies` for object literals that must match a contract.\n\n## Parameters and returns\n\n```typescript\n// Bad\nfunction readId(value: any): any {\n\treturn value.id;\n}\n\n// Good — validate unknown input.\nfunction readId(value: unknown): string | undefined {\n\tif (value && typeof value === \"object\" && \"id\" in value) {\n\t\tconst candidate = value.id; // `in` narrowing types this as unknown — no cast needed\n\t\treturn typeof candidate === \"string\" ? candidate : undefined;\n\t}\n}\n```\n\n## Assertions\n\n```typescript\n// Bad\nconst root = document.getElementById(\"root\") as any;\nroot.innerText = \"ready\";\n\n// Good\nconst root = document.getElementById(\"root\") as HTMLElement | null;\nroot?.innerText = \"ready\";\n```\n\n## Object literals\n\n```typescript\n// Bad\nconst config = { port: 3000 } as any as ServerConfig;\n\n// Good\nconst config = { port: 3000 } satisfies ServerConfig;\n```\n\n## Choosing: guard vs schema vs unchecked cast\n\n|Situation|Reach for|\n|---|---|\n|Data from outside your control — network/RPC, parsed JSON, config files, env vars, CLI/IPC, persisted blobs — or a shape reused across the codebase|**Schema parse** (Zod/Valibot/…): runtime validation, typed output, and a clear error on bad shape|\n|In-process value the compiler merely lost track of — an `unknown` from a generic, a union to discriminate, a one-off read of a field or two|**Type guard** (`in` / `typeof`): no dependency, but it only checks what you write, so keep the checked surface small|\n|You genuinely know more than the compiler *and* a runtime check is impossible or meaningless — a well-known DOM node (`as HTMLElement`), structurally-identical types inference can't unify, a library type that is wrong or unexpressible, `as const`|**Unchecked cast** (`as` / `as unknown as T`): assign to a named const with a one-line reason; never for raw external input|\n\nIf a library boundary truly requires an unchecked cast, use `as unknown as T` with a short reason. Never leave a bare `any`.\n",
  "ts-no-deprecated-leftovers": "---\ndescription: \"Do not leave `@deprecated` shims behind after refactors — update call sites and remove the old API\"\ncondition: \"@deprecated\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nNever use `@deprecated` instead of completing a refactor. Obsolete APIs in code you control: update every call site; remove the old name in the same change.\n\n## Why\n\n- Deprecated aliases: two live contracts.\n- Future maintainers preserve behavior nobody should call.\n- Tests pass while production uses the old path.\n- Next refactor unwinds real API and compatibility layer.\n\n## Avoid\n\n```typescript\n// Bad — leaves a stale compatibility name instead of finishing the cutover.\n/** @deprecated Use loadSettings instead. */\nexport const loadConfig = loadSettings;\n\n// Bad — preserves an obsolete wrapper after callers can be updated.\n/** @deprecated Use createClient instead. */\nexport function makeClient(options: ClientOptions): Client {\n\treturn createClient(options);\n}\n```\n\n## Use\n\n```typescript\n// Update all imports and call sites to the durable name.\nexport function loadSettings(path: string): Settings { ... }\nexport function createClient(options: ClientOptions): Client { ... }\n```\n\n## Exceptions\n\n- Public package APIs with a documented migration window.\n- Third-party declarations whose deprecated marker reflects an external contract.\n- Tests intentionally verifying deprecated API behavior during a supported transition.\n\nIf an exception applies, state the external compatibility requirement. Otherwise complete the refactor; delete the deprecated symbol.\n",
  "ts-no-dynamic-import": "---\ndescription: \"Do not use `await import()` — use static imports unless dynamic loading is unavoidable\"\ncondition: \"await import\\\\(\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nUse static imports for modules known at author time. Reach for `await import()` only when the module specifier is genuinely runtime-selected.\n\n## Why\n\n- Static imports fail during build, not under load.\n- Bundlers, type checkers, and tree shakers see them.\n- The dependency graph remains reviewable.\n- Consumers keep precise module types without casts.\n\n## Avoid\n\n```typescript\n// Bad — the module path is a literal.\nconst { createClient } = await import(\"some-sdk\");\n\n// Bad — dynamic import followed by a shape assertion.\nconst mod = (await import(\"./known-module\")) as { run?: unknown };\n```\n\n## Use\n\n```typescript\nimport { createClient } from \"some-sdk\";\nimport { run } from \"./known-module\";\n```\n\n## Exceptions\n\n- Plugin loading from a runtime registry.\n- Platform-specific modules that do not exist everywhere.\n- Test cases that intentionally exercise module loading boundaries.\n\nException? Add a short comment naming why static import cannot work.\n",
  "ts-no-inline-cast-access": "---\ndescription: \"Don't assert an inline object type and immediately read a property — `(x as { y: T }).y` trusts an unchecked shape; validate with a schema parse at trust boundaries, narrow with `in`/`typeof`, or use a validated named type\"\nscope: \"tool:edit(*.{ts,tsx,mts,cts}), tool:write(*.{ts,tsx,mts,cts})\"\ninterruptMode: never\nastCondition:\n  - \"($X as { $$$BODY }).$PROP\"\n  - \"($X as { $$$BODY })?.$PROP\"\n  - \"($X as { $$$BODY })[$IDX]\"\n---\n\n## Don't inline-cast an object type for member access\n\n`(value as { content: unknown }).content` fabricates an unchecked shape, then trusts it for the access. If `value` lacks that shape, the read is silently wrong; no type error fires.\n\n## Why\n\n- Unchecked assertion: suppresses the error; proves no shape.\n- Localizes the lie; readers cannot tell whether `value` was validated.\n- Usually replace with runtime narrowing or a validated boundary type.\n\n## Avoid\n\n```ts\nconst content = (value as { content: unknown }).content;\nconst id = (resp as { data: { id: string } }).data.id;\nconst name = (payload as { name?: string })?.name;\nconst flag = (opts as { enabled: boolean })[\"enabled\"];\n```\n\n## Use\n\nAt a boundary, prefer a schema parse when a validator exists: validate once, then read a fully typed value.\n\n```ts\nimport { type } from \"@oh-my-pi/omptype\";\n\nconst Resp = type({ data: { id: \"string\" } });\n\nconst resp = Resp.assert(raw); // throws on bad input; resp.data.id is typed string\nconst id = resp.data.id;\n```\n\nFor a one-off field read, narrow with `in` / `typeof`; access is checked. After `\"content\" in value`, TypeScript infers the property as `unknown`:\n\n```ts\nif (value && typeof value === \"object\" && \"content\" in value) {\n\tconst content = value.content; // unknown — validate before use\n}\n```\n\n## Choose: guard vs schema vs unchecked cast\n\n- Outside-controlled data—network/RPC, parsed JSON, config files, env vars, CLI/IPC, persisted blobs—or codebase-reused shapes: **Schema parse** (Zod/Valibot/…): runtime validation, typed output, clear bad-shape error.\n- In-process values the compiler lost—generic `unknown`, union discrimination, one-off reads of one or two fields: **Type guard** (`in` / `typeof`): no dependency; checks only what you write, so keep its surface small.\n- You know more than the compiler **and** runtime checking is impossible or meaningless—well-known DOM node (`as HTMLElement`), structurally-identical types inference cannot unify, wrong or unexpressible library type, `as const`: **Unchecked cast** (`as`): assign to a named const with a one-line reason; never raw external input or inline member access.\n",
  "ts-no-local-is-record": "---\ndescription: \"Never use isRecord\"\ncondition:\n  - \"\\\\bfunction\\\\s+isRecord(?:\\\\s*<[^>]*>)?\\\\s*\\\\(\"\n  - \"\\\\b(?:const|let|var)\\\\s+isRecord\\\\b\\\\s*(?::[\\\\s\\\\S]{0,300}?)?=\\\\s*(?:async\\\\s+)?(?:function\\\\b|(?:<[^>\\\\n]*>\\\\s*)?(?:\\\\([^)]*\\\\)|[A-Za-z_$][\\\\w$]*)\\\\s*(?::[\\\\s\\\\S]{0,300}?)?=>)\"\nscope: \"tool:edit(*.{ts,tsx,mts,cts}), tool:write(*.{ts,tsx,mts,cts})\"\ninterruptMode: never\n---\n\n## Why it's wrong\n\n- A `Record<string, unknown>` guard proves an object, not its fields.\n- Either unnecessarily complicated or insufficiently strong.\n- Repeated guards hide the data contract from readers and TypeScript.\n\n## Use\n\n`isRecord`: values narrow to `Record<string, unknown>`; fields remain `unknown`.\n\nNetwork, config, IPC, persisted, or reused data shapes: parse once at the boundary with the project's schema validator; consume its named output type:\n\n```typescript\nconst Config = z.object({ retries: z.number().int().nonnegative() });\ntype Config = z.infer<typeof Config>;\n\nconst config = Config.parse(raw);\n```\n\nIf runtime shape uncertain: check used properties with `typeof`, `Array.isArray`, `in`, or a discriminant. If an existing invariant guarantees shape: assert the named type at that boundary, not a duplicate guard:\n\n```typescript\nconst config = value as Config;\n```\n\n## Avoid\n\n```typescript\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n\treturn !!value && typeof value === \"object\" && !Array.isArray(value);\n}\n\nconst isRecord = (value: unknown): value is Record<string, unknown> =>\n\tvalue !== null && typeof value === \"object\";\n```\n\n## Exceptions\n\nA standalone package without a shared type-guard module may define one canonical guard. Export it from the package's type-guard module; never recreate it at individual call sites.\n",
  "ts-no-return-type": "---\ndescription: \"Do not use `ReturnType<typeof fn>` — name the type explicitly\"\ncondition: \"ReturnType<\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nDo not publish contracts through `ReturnType<typeof fn>`. Name the type at the module that owns the value and import that name at consumers.\n\n## Why\n\n- Named types document the contract directly.\n- Consumers stop coupling to implementation helpers.\n- JSDoc and changelog notes attach to the exported type.\n- Type errors point at the intended API boundary.\n\n## Avoid\n\n```typescript\n// Bad — opaque and coupled to implementation names.\ntype Config = Awaited<ReturnType<typeof loadConfig>>;\ntype Message = ReturnType<typeof buildMessage>[\"message\"];\nlet service: ReturnType<typeof createService> | undefined;\n```\n\n## Use\n\n```typescript\n// In the module that owns the function:\nexport interface LoadedConfig {\n\tpath: string;\n\tvalues: Record<string, unknown>;\n}\n\nexport function loadConfig(path: string): Promise<LoadedConfig> { ... }\n\n// At the consumer:\nimport type { LoadedConfig } from \"./config\";\n```\n\n## Exceptions\n\n- Generic type utilities where the function is a type parameter.\n\nConcrete function? Export a concrete type.\n",
  "ts-no-test-timers": "---\ndescription: Do not use real timers (Bun.sleep, setTimeout, setInterval) in tests — drive time with fake timers instead\ncondition:\n  - \"Bun\\\\.sleep\\\\(\"\n  - \"\\\\bsetInterval\\\\(\"\n  - \"\\\\bsetTimeout\\\\(\"\nscope: \"tool:edit(*.test.ts), tool:write(*.test.ts)\"\ninterruptMode: never\n---\n\n**Avoid real wall-clock timers in test files.** `Bun.sleep(...)`, `setTimeout(...)`, and `setInterval(...)` bind duration to real time → fixed latency each invocation; CI pays every run. “Long enough” sleeps guess at and mask races; under load, races resurface and flake. Fixed waits hide the awaited condition, so failures point to a timeout, not the cause.\n\n## Avoid\n\n```typescript\ntest(\"debounce fires once\", async () => {\n\tconst fn = debounce(handler, 100);\n\tfn();\n\tawait Bun.sleep(150); // real delay — slow and timing-dependent\n\texpect(handler).toHaveBeenCalledTimes(1);\n});\n```\n\n## Use\n\nDrive time deterministically with fake timers:\n\n```typescript\nimport { expect, test, vi } from \"bun:test\";\n\ntest(\"debounce fires once\", () => {\n\tvi.useFakeTimers();\n\tconst fn = debounce(handler, 100);\n\tfn();\n\tvi.advanceTimersByTime(150); // advance the clock, no real wait\n\texpect(handler).toHaveBeenCalledTimes(1);\n});\n```\n\nWhen code resolves a promise or emits an event, await that signal, not a guessed duration:\n\n```typescript\nawait once(emitter, \"done\"); // await the real event\nconst value = await pending; // await the promise the code already exposes\n```\n\n## Exceptions\n\nIntegration tests deliberately exercising real timer behavior against the platform clock may need a genuine delay. Keep rare; add a short comment naming why deterministic time control will not work.\n",
  "ts-no-tiny-functions": "---\ndescription: \"Do not extract 1-2 line functions that only wrap an expression — inline them\"\ncondition: \"(?m)\\\\{\\\\s*return [^;{}\\\\n]+;?\\\\s*\\\\}|\\\\b(?:const|let|var)\\\\s+[\\\\w$]+\\\\s*=\\\\s*(\\\\([^)]*\\\\)|[a-zA-Z_$][\\\\w$]*)\\\\s*=>\\\\s*[^{\\\\n]+$\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nInline functions whose whole body: one expression or `return`, unless name creates a durable contract.\n\n## Why\n\n- One-line wrappers: no real behavior.\n- Readers: jump to verify trivial code.\n- Signature: freezes shape too early.\n- Inline expressions: better search and type flow.\n\n## Avoid\n\n```typescript\n// Bad — pure rename, no behavior added.\nfunction isEmpty(value: string): boolean {\n\treturn value.length === 0;\n}\n\nconst getDisplayName = (user: User) => user.profile.displayName;\n\nfunction double(value: number) {\n\treturn value * 2;\n}\n\nif (isEmpty(name)) { ... }\n```\n\n## Use\n\n```typescript\nif (name.length === 0) { ... }\nconst displayName = user.profile.displayName;\nconst doubled = value * 2;\n```\n\n## Allowed tiny functions\n\n- Three or more call sites need lockstep behavior.\n- Exported name: stable domain concept.\n- Callback identity matters.\n- Type guard preserves narrowing.\n- Public API, test seam, or DI boundary needs indirection.\n- Names non-obvious formula or magic-constant computation the inlined expression would not explain alone.\n\nIf none apply, inline it.\n",
  "ts-promise-with-resolvers": "---\ndescription: Use Promise.withResolvers() instead of new Promise() constructor\ncondition: \"new Promise\\\\(\"\nscope: \"tool:edit(*.ts), tool:edit(*.tsx), tool:write(*.ts), tool:write(*.tsx)\"\ninterruptMode: never\n---\n\nPrefer `Promise.withResolvers()` over `new Promise((resolve, reject) => ...)`: linear control flow; typed resolvers without callback nesting.\n\n## Basic operation\n\n```typescript\n// Bad\nfunction delay(ms: number): Promise<void> {\n\treturn new Promise(resolve => {\n\t\tsetTimeout(resolve, ms);\n\t});\n}\n\n// Good\nfunction delay(ms: number): Promise<void> {\n\tconst { promise, resolve } = Promise.withResolvers<void>();\n\tsetTimeout(resolve, ms);\n\treturn promise;\n}\n```\n\n## Event-based completion\n\n```typescript\n// Bad\nfunction waitForEvent(emitter: EventEmitter, event: string): Promise<unknown> {\n\treturn new Promise((resolve, reject) => {\n\t\temitter.once(event, resolve);\n\t\temitter.once(\"error\", reject);\n\t});\n}\n\n// Good\nfunction waitForEvent(emitter: EventEmitter, event: string): Promise<unknown> {\n\tconst { promise, resolve, reject } = Promise.withResolvers<unknown>();\n\temitter.once(event, resolve);\n\temitter.once(\"error\", reject);\n\treturn promise;\n}\n```\n\n## Stored resolver\n\n```typescript\nclass Gate {\n\t#promise: Promise<void>;\n\t#resolve: () => void;\n\n\tconstructor() {\n\t\tconst { promise, resolve } = Promise.withResolvers<void>();\n\t\tthis.#promise = promise;\n\t\tthis.#resolve = resolve;\n\t}\n\n\topen(): void { this.#resolve(); }\n\twait(): Promise<void> { return this.#promise; }\n}\n```\n\nConstructor only if an API specifically requires executor form.\n",
  "ts-redundant-clear-guard": "---\ndescription: Do not guard clearTimeout/clearInterval/clearImmediate with a truthiness or null/undefined check — they accept null and undefined\nscope: \"tool:edit(*.{ts,tsx,js,jsx,mts,cts,mjs,cjs}), tool:write(*.{ts,tsx,js,jsx,mts,cts,mjs,cjs})\"\ninterruptMode: never\nastCondition:\n  - \"if ($X) clearTimeout($X)\"\n  - \"if ($X) { clearTimeout($X) }\"\n  - \"if ($X) clearInterval($X)\"\n  - \"if ($X) { clearInterval($X) }\"\n  - \"if ($X) clearImmediate($X)\"\n  - \"if ($X) { clearImmediate($X) }\"\n  - \"if ($X !== null) clearTimeout($X)\"\n  - \"if ($X !== null) { clearTimeout($X) }\"\n  - \"if ($X !== null) clearInterval($X)\"\n  - \"if ($X !== null) { clearInterval($X) }\"\n  - \"if ($X !== null) clearImmediate($X)\"\n  - \"if ($X !== null) { clearImmediate($X) }\"\n  - \"if ($X != null) clearTimeout($X)\"\n  - \"if ($X != null) { clearTimeout($X) }\"\n  - \"if ($X != null) clearInterval($X)\"\n  - \"if ($X != null) { clearInterval($X) }\"\n  - \"if ($X != null) clearImmediate($X)\"\n  - \"if ($X != null) { clearImmediate($X) }\"\n  - \"if ($X !== undefined) clearTimeout($X)\"\n  - \"if ($X !== undefined) { clearTimeout($X) }\"\n  - \"if ($X !== undefined) clearInterval($X)\"\n  - \"if ($X !== undefined) { clearInterval($X) }\"\n  - \"if ($X !== undefined) clearImmediate($X)\"\n  - \"if ($X !== undefined) { clearImmediate($X) }\"\n  - \"if ($X != undefined) clearTimeout($X)\"\n  - \"if ($X != undefined) { clearTimeout($X) }\"\n  - \"if ($X != undefined) clearInterval($X)\"\n  - \"if ($X != undefined) { clearInterval($X) }\"\n  - \"if ($X != undefined) clearImmediate($X)\"\n  - \"if ($X != undefined) { clearImmediate($X) }\"\n---\n\n**Do not guard `clearTimeout` / `clearInterval` / `clearImmediate` with truthiness or `null`/`undefined` checks.** Per WHATWG/Node timers spec, calls no-op for `null`, `undefined`, or values without a live timer; guards cannot change behavior, add branches readers must reason about, inflate code, hide the line that matters, and signal timer-API misunderstanding.\n\n## Avoid\n\n```ts\nif (this.timer) clearTimeout(this.timer);\nif (handle !== null) clearInterval(handle);\nif (id != undefined) {\n\tclearImmediate(id);\n}\n```\n\n## Use\n\n```ts\nclearTimeout(this.timer);\nclearInterval(handle);\nclearImmediate(id);\n```\n\n## When a guard *is* warranted\n\nKeep it only if the body does more than clear, e.g. reassigns the handle or runs other cleanup:\n\n```ts\nif (this.timer) {\n\tclearTimeout(this.timer);\n\tthis.timer = undefined; // extra work → guard is not purely redundant\n}\n```\n\nRule fires only if the clear call is the guarded branch's sole statement; legitimate cases are left alone.\n",
  "ts-set-map": "---\ndescription: Prefer Record<K, V> for small static literals; use Set/Map for anything dynamic\ncondition: \"\\\\bnew\\\\s+(Set|Map)\\\\b\"\nscope: \"tool:edit(**/*.{ts,tsx}), tool:write(**/*.{ts,tsx})\"\ninterruptMode: never\n---\n\nSmall, static string-keyed lookup tables: `Record<K, V>` / `Record<K, true>`.\n\n`Set` / `Map`: dynamic/non-string keys; runtime insertion/deletion; `.size`, `.clear()`, stable insertion order, or iterator APIs.\n\n```typescript\n// Static literal → Record\nconst LABEL_BY_KIND: Record<string, string> = {\n\ttext: \"Text\",\n\tjson: \"JSON\",\n\tbinary: \"Binary\",\n};\n\n// Dynamic membership → Set\nconst seen = new Set<string>();\nfor (const item of items) {\n\tif (seen.has(item.id)) continue;\n\tseen.add(item.id);\n}\n```\n",
};
